const lines = require('fs').readFileSync('/dev/stdin', 'utf8').split('\n');
const n = parseInt(lines[0]);
let s = lines[1] ? lines[1].trim() : '';

let arr = s.split('');
let removed = 0;

for (let letterCode = 1; letterCode < 26; letterCode++) {
    let target = String.fromCharCode('a'.charCodeAt(0) + letterCode);
    let prevChar = String.fromCharCode('a'.charCodeAt(0) + letterCode - 1);

    let foundSomething = true;
    while (foundSomething) {
        foundSomething = false;
        for (let i = 0; i < arr.length; i++) {
            if (arr[i] === target) {
                let leftOk = (i - 1 >= 0) && arr[i - 1] === prevChar;
                let rightOk = (i + 1 < arr.length) && arr[i + 1] === prevChar;
                if (leftOk || rightOk) {
                    arr.splice(i, 1);
                    removed++;
                    foundSomething = true;
                    break;
                }
            }
        }
    }
}

console.log(removed);
